CREATE PROCEDURE dbo.GetCustomer
  @CustomerId INT
AS
BEGIN
  SET NOCOUNT ON;
  SELECT * FROM dbo.Customers WHERE Id = @CustomerId;
END

CREATE VIEW dbo.SalesByRegion WITH SCHEMABINDING AS
SELECT RegionId, COUNT_BIG(*) AS Cnt, SUM(Amount) AS Total
FROM dbo.Sales GROUP BY RegionId;

CREATE PROCEDURE dbo.GetTotal
  @CustomerId INT, @Total DECIMAL(10,2) OUTPUT
AS
  SELECT @Total = SUM(Total) FROM dbo.Orders WHERE CustomerId = @CustomerId;

